    return '<svg class="ac-chart" viewBox="0 0 ' + W + " " + H + '" role="img" aria-label="' + esc(shortName(c)) + ' runs"><text class="ohlc" x="4" y="12">' + head + "</text>" + out + "</svg>" + note;
