/* ══ Motion ══════════════════════════════════════════════════════════════════
 * On by default (html.fx); the top-bar switch removes the class and with it every rule below.
 * Heavy ease-out, overshoot on landings, one long cinematic intro. Numbers decode to their exact values. */

/* Intro: the radar */
.sr-intro { position: fixed; inset: 0; z-index: 60; background: var(--bg-app); display: grid; cursor: pointer; transition: opacity .7s var(--ease-settle), transform .9s var(--ease-settle), filter .7s ease; }
