.sr-intro-mark { font-size: clamp(40px, 7vw, 92px); line-height: 1; font-weight: 600; letter-spacing: -.05em; white-space: nowrap; }
.sr-intro-mark span { display: inline-block; opacity: 0; transform: translateY(40%) scale(.9); filter: blur(8px); animation: sr-letter .9s var(--ease-settle) forwards; animation-delay: calc(900ms + var(--k) * 55ms); }
