.sr-intro.is-out { opacity: 0; transform: scale(1.08); filter: blur(6px); pointer-events: none; }
@keyframes sr-letter { to { opacity: 1; transform: none; filter: none; } }

/* The live field sits behind the verdict's content */
.sr-field { position: absolute; inset: 0; z-index: 0; pointer-events: none; }
.fx .ac-verdict { background-image: none; }
.ac-verdict-grid { z-index: 1; }

