.sr-tilt { position: relative; transition: transform .6s var(--ease-settle), border-color .2s ease; transform-style: preserve-3d; will-change: transform; }
.sr-tilt.is-tilting { transition: transform .08s linear, border-color .2s ease; border-color: var(--border-control); }
