/* Intro: the radar */
.sr-intro { position: fixed; inset: 0; z-index: 60; background: var(--bg-app); display: grid; cursor: pointer; transition: opacity .7s var(--ease-settle), transform .9s var(--ease-settle), filter .7s ease; }
.sr-intro canvas { position: absolute; inset: 0; }
.sr-intro-copy { position: absolute; left: 0; right: 0; bottom: 9vh; display: grid; justify-items: center; gap: var(--space-4); padding: 0 var(--space-4); text-align: center; pointer-events: none; }
.sr-intro-mark { font-size: clamp(40px, 7vw, 92px); line-height: 1; font-weight: 600; letter-spacing: -.05em; white-space: nowrap; }
.sr-intro-mark span { display: inline-block; opacity: 0; transform: translateY(40%) scale(.9); filter: blur(8px); animation: sr-letter .9s var(--ease-settle) forwards; animation-delay: calc(900ms + var(--k) * 55ms); }
.sr-intro-line { display: flex; flex-wrap: wrap; justify-content: center; gap: var(--space-3); min-height: 24px; font: 500 15px/22px var(--font-mono); color: var(--text-secondary); }
.sr-intro-line span { opacity: 0; animation: sr-rise .6s var(--ease-settle) forwards; animation-delay: calc(var(--k) * 140ms); }
.sr-intro-line i { font-style: normal; color: var(--text-tertiary); }
.sr-intro-skip { position: absolute; right: var(--space-5); bottom: calc(var(--space-5) + env(safe-area-inset-bottom, 0px)); height: 32px; padding: 0 var(--space-3); border-radius: var(--radius-full); border: 1px solid var(--border-control); background: transparent; color: var(--text-secondary); font: 500 13px/18px var(--font-sans); cursor: pointer; }
.sr-intro.is-out { opacity: 0; transform: scale(1.08); filter: blur(6px); pointer-events: none; }
@keyframes sr-letter { to { opacity: 1; transform: none; filter: none; } }

/* The live field sits behind the verdict's content */
.sr-field { position: absolute; inset: 0; z-index: 0; pointer-events: none; }
.fx .ac-verdict { background-image: none; }
.ac-verdict-grid { z-index: 1; }

/* Cursor ring */
.sr-cursor { position: fixed; left: -18px; top: -18px; width: 36px; height: 36px; z-index: 70; border-radius: var(--radius-full); border: 1.5px solid var(--text-secondary); pointer-events: none; transition: width .3s var(--ease-settle), height .3s var(--ease-settle), left .3s var(--ease-settle), top .3s var(--ease-settle), background-color .2s ease, border-color .2s ease; mix-blend-mode: difference; }
.sr-cursor.is-hot { width: 64px; height: 64px; left: -32px; top: -32px; border-color: var(--up); background: var(--up-soft); }
.sr-cursor.is-down { width: 26px; height: 26px; left: -13px; top: -13px; }

/* Tilt and sheen */
.sr-tilt { position: relative; transition: transform .6s var(--ease-settle), border-color .2s ease; transform-style: preserve-3d; will-change: transform; }
.sr-tilt.is-tilting { transition: transform .08s linear, border-color .2s ease; border-color: var(--border-control); }
.fx .sr-tilt::after { content: ""; position: absolute; inset: 0; border-radius: inherit; pointer-events: none; opacity: 0; transition: opacity .3s ease;
  background: radial-gradient(420px circle at var(--gx, 50%) var(--gy, 50%), rgba(255, 255, 255, .07), transparent 60%); }
.fx .sr-tilt.is-tilting::after { opacity: 1; }
.ac-btn, .sr-chip, .ac-seg button { transition: transform .45s var(--ease-settle), background-color .15s ease, color .15s ease, border-color .15s ease; }

/* Entrances: every screen assembles itself */
.fx .sr-enter > * { animation: sr-rise-big .95s var(--ease-settle) both; animation-delay: calc(var(--i, 0) * 90ms); }
.fx .sr-play .ac-hero-xl .w > span { animation: sr-word 1.05s var(--ease-settle) both; animation-delay: calc(150ms + var(--w) * 45ms); }
.fx .sr-play .ac-hero-xl em { animation: sr-underline 1s var(--ease-settle) both; animation-delay: 2.2s; }
.fx .sr-play .ac-lede { animation: sr-rise .9s var(--ease-settle) both; animation-delay: .6s; }
.fx .sr-play .ac-figures { animation: sr-rise .9s var(--ease-settle) both; animation-delay: .75s; }
.fx .sr-play .ac-matrix { animation: sr-slide-in 1.1s var(--ease-settle) both; animation-delay: .35s; }
.fx .sr-play .ac-mrow { animation: sr-row .8s var(--ease-settle) both; animation-delay: calc(500ms + var(--row, 0) * 70ms); }

/* Matrix: each square drops in hard, diagonal wave; each score lands with a flash */
.fx .sr-play .ac-cells i { animation: sr-slam .6s var(--ease-settle) both; animation-delay: calc(900ms + var(--r) * 110ms + var(--c) * 60ms); }
.fx .sr-play .ac-mscore { animation: sr-score-pop .7s var(--ease-settle) both; animation-delay: calc(1250ms + var(--r) * 110ms); }

