.fx .sr-play .sr-pulse { animation: sr-travel 2.6s var(--ease-press) 1s both; box-shadow: 0 0 0 6px var(--up-soft); }
.fx .sr-play .sr-node-dot { animation: sr-node .7s var(--ease-settle) both; animation-delay: calc(1.05s + var(--n) * 360ms); }
.fx .sr-node-dot { transition: transform .5s var(--ease-settle), border-color .2s ease, color .2s ease; }
@media (hover: hover) { .fx .sr-node:hover .sr-node-dot { transform: scale(1.12) rotate(-6deg); border-color: var(--up); color: var(--up); } }

