.fx .sr-chain-play .ac-step { animation: sr-deal .9s var(--ease-settle) both; animation-delay: calc(var(--s) * 480ms); transform-origin: left center; }
.fx .sr-chain-play .ac-step:not(:last-child)::after { animation: sr-draw .45s ease both; animation-delay: calc(var(--s) * 480ms + 420ms); transform-origin: left; }
.fx .sr-chain-play .ac-struck::after { animation: sr-draw .5s var(--ease-settle) both; animation-delay: 2.1s; }
.fx .sr-chain-play .ac-struck { animation: sr-glitch .6s steps(2, end) 2.55s both; }
.fx .sr-chain-play .ac-step--verdict { animation: sr-deal .9s var(--ease-settle) both, sr-alarm 1.2s ease 2.5s both; animation-delay: calc(var(--s) * 480ms), 2.5s; }
.fx .sr-chain-play .sr-stamp { animation: sr-slam .7s var(--ease-settle) both; animation-delay: 2.7s; }
.ac-step--verdict { position: relative; }
.fx .sr-chain-play .ac-step--verdict::before { content: ""; position: absolute; left: 50%; top: 50%; width: 40px; height: 40px; margin: -20px; border-radius: var(--radius-full); border: 2px solid var(--down); opacity: 0; pointer-events: none; animation: sr-shock 1.1s var(--ease-settle) 2.55s both; }

