@keyframes sr-score-pop { 0% { opacity: 0; transform: scale(.4); } 50% { opacity: 1; transform: scale(1.35); text-shadow: 0 0 18px var(--up); } 100% { opacity: 1; transform: none; text-shadow: none; } }
@keyframes sr-travel { 0% { opacity: 0; left: 4%; } 5% { opacity: 1; } 95% { opacity: 1; } 100% { opacity: 0; left: 96%; } }
