@keyframes sr-deal { from { opacity: 0; transform: rotateY(-75deg) translateX(-30px); } to { opacity: 1; transform: none; } }
@keyframes sr-draw { from { transform: scaleX(0); } to { transform: scaleX(1); } }
@keyframes sr-glitch { 0% { transform: translate(0); text-shadow: none; } 20% { transform: translate(-3px, 1px); text-shadow: 3px 0 var(--down), -3px 0 var(--accent); } 40% { transform: translate(3px, -1px); text-shadow: -3px 0 var(--down), 3px 0 var(--accent); } 60% { transform: translate(-2px, 0); } 80% { transform: translate(2px, 1px); text-shadow: 2px 0 var(--down); } 100% { transform: none; text-shadow: none; } }
@keyframes sr-alarm { 0%, 100% { box-shadow: 0 0 0 0 transparent; } 30% { box-shadow: 0 0 0 6px var(--down-soft), 0 0 60px var(--down-soft); } }
@keyframes sr-shock { 0% { opacity: .9; transform: scale(.3); } 100% { opacity: 0; transform: scale(9); } }
@keyframes sr-spring-up { 0% { transform: scaleY(0); } 60% { transform: scaleY(1.12); } 80% { transform: scaleY(.96); } 100% { transform: scaleY(1); } }
@keyframes sr-grow { from { opacity: 0; transform: scaleY(.2); } to { opacity: 1; transform: none; } }
@keyframes sr-shake { 0%, 100% { transform: none; } 20% { transform: translateX(-6px); } 40% { transform: translateX(5px); } 60% { transform: translateX(-3px); } 80% { transform: translateX(2px); } }
@keyframes sr-unfold { from { opacity: 0; transform: scaleY(.6) translateY(-8px); } to { opacity: 1; transform: none; } }
@keyframes sr-scroll-in { from { opacity: .2; transform: translateY(70px) scale(.94); } to { opacity: 1; transform: none; } }
@keyframes sr-drift { to { transform: translateY(80px); opacity: .35; } }
@keyframes sr-recede { to { opacity: 0; transform: scale(.94); filter: blur(4px); } }
@keyframes sr-iris { from { clip-path: circle(0 at var(--wx, 50%) var(--wy, 0)); } to { clip-path: circle(150% at var(--wx, 50%) var(--wy, 0)); } }
