.fx .ac-chart .bar-up, .fx .ac-chart .bar-down, .fx .ac-chart .bar-accent, .fx .ac-chart .bar-neutral { transform-box: fill-box; transform-origin: bottom; animation: sr-spring-up 1s var(--ease-settle) both; animation-delay: calc(var(--i, 0) * 55ms + .2s); }
.fx .ac-chart .ghost { transform-box: fill-box; transform-origin: bottom; animation: sr-grow .8s var(--ease-settle) both; }
.fx .ac-chart .col { transition: opacity .2s ease; }
@media (hover: hover) { .fx .ac-chart:hover .col { opacity: .55; } .fx .ac-chart .col:hover { opacity: 1; } }

/* Planted cells */
.fx .sr-play-cells .ac-cell { animation: sr-deal .8s var(--ease-settle) both; animation-delay: calc(var(--i) * 70ms + .3s); }
.fx .sr-play-cells .ac-cell-mark { animation: sr-slam .6s var(--ease-settle) both; animation-delay: calc(var(--i) * 70ms + .55s); }

/* Replay */
.fx .sr-tl.is-replaying .sr-tl-row { opacity: .22; }
.fx .sr-tl.is-replaying .sr-tl-row.is-lit { opacity: 1; }
.fx .sr-tl-row.is-lit .sr-tl-dot { animation: sr-slam .5s var(--ease-settle) both; }
.fx .sr-tl-row.is-lit.sr-tl-row--failed { animation: sr-shake .45s ease both; }
.fx .sr-tl-row.is-lit .sr-decision { animation: sr-unfold .6s var(--ease-settle) both; transform-origin: top; }
.fx .sr-tl-row.is-lit .sr-opt--chosen { animation: sr-slam .6s var(--ease-settle) .35s both; }

/* Scroll: blocks below the fold settle as they arrive; the hero drifts as you scroll */
@supports (animation-timeline: view()) {
  .fx .sr-scroll { animation: sr-scroll-in linear both; animation-timeline: view(); animation-range: entry 0% cover 28%; }
  .fx .ac-verdict-grid { animation: sr-drift linear both; animation-timeline: scroll(root); animation-range: 0 700px; }
}

/* Page change: the new screen opens as a circle from the click */
.fx ::view-transition-old(main) { animation: sr-recede .45s var(--ease-settle) both; }
.fx ::view-transition-new(main) { animation: sr-iris .75s var(--ease-settle) both; }

.fx .ac-nav a { transition: background-color .2s ease, transform .35s var(--ease-settle); }
@media (hover: hover) { .fx .ac-nav a:hover { transform: translateX(4px); } }

.sr-motion[aria-pressed="false"] { color: var(--text-tertiary); }

@keyframes sr-rise { from { opacity: 0; transform: translateY(16px); } to { opacity: 1; transform: none; } }
@keyframes sr-rise-big { from { opacity: 0; transform: translateY(46px) scale(.97); filter: blur(6px); } to { opacity: 1; transform: none; filter: none; } }
@keyframes sr-word { from { transform: translateY(110%) rotate(4deg); } to { transform: none; } }
@keyframes sr-underline { from { background-size: 0% 3px; } to { background-size: 100% 3px; } }
@keyframes sr-slide-in { from { opacity: 0; transform: translateX(60px) rotateY(-12deg); } to { opacity: 1; transform: none; } }
@keyframes sr-slam { 0% { opacity: 0; transform: scale(2.4) rotate(-12deg); } 55% { opacity: 1; transform: scale(.86) rotate(2deg); } 78% { transform: scale(1.08); } 100% { opacity: 1; transform: none; } }
@keyframes sr-score-pop { 0% { opacity: 0; transform: scale(.4); } 50% { opacity: 1; transform: scale(1.35); text-shadow: 0 0 18px var(--up); } 100% { opacity: 1; transform: none; text-shadow: none; } }
@keyframes sr-travel { 0% { opacity: 0; left: 4%; } 5% { opacity: 1; } 95% { opacity: 1; } 100% { opacity: 0; left: 96%; } }
@keyframes sr-node { 0% { transform: scale(1); } 35% { transform: scale(1.3); border-color: var(--up); color: var(--up); box-shadow: 0 0 0 10px var(--up-soft); } 100% { transform: none; } }
@keyframes sr-deal { from { opacity: 0; transform: rotateY(-75deg) translateX(-30px); } to { opacity: 1; transform: none; } }
@keyframes sr-draw { from { transform: scaleX(0); } to { transform: scaleX(1); } }
@keyframes sr-glitch { 0% { transform: translate(0); text-shadow: none; } 20% { transform: translate(-3px, 1px); text-shadow: 3px 0 var(--down), -3px 0 var(--accent); } 40% { transform: translate(3px, -1px); text-shadow: -3px 0 var(--down), 3px 0 var(--accent); } 60% { transform: translate(-2px, 0); } 80% { transform: translate(2px, 1px); text-shadow: 2px 0 var(--down); } 100% { transform: none; text-shadow: none; } }
@keyframes sr-alarm { 0%, 100% { box-shadow: 0 0 0 0 var(--down-soft); } 30% { box-shadow: 0 0 0 6px var(--down-soft), 0 0 60px var(--down-soft); } }
@keyframes sr-shock { 0% { opacity: .9; transform: scale(.3); } 100% { opacity: 0; transform: scale(9); } }
@keyframes sr-spring-up { 0% { transform: scaleY(0); } 60% { transform: scaleY(1.12); } 80% { transform: scaleY(.96); } 100% { transform: scaleY(1); } }
@keyframes sr-grow { from { opacity: 0; transform: scaleY(.2); } to { opacity: 1; transform: none; } }
@keyframes sr-shake { 0%, 100% { transform: none; } 20% { transform: translateX(-6px); } 40% { transform: translateX(5px); } 60% { transform: translateX(-3px); } 80% { transform: translateX(2px); } }
@keyframes sr-unfold { from { opacity: 0; transform: scaleY(.6) translateY(-8px); } to { opacity: 1; transform: none; } }
@keyframes sr-scroll-in { from { opacity: .2; transform: translateY(70px) scale(.94); } to { opacity: 1; transform: none; } }
@keyframes sr-drift { to { transform: translateY(80px); opacity: .35; } }
@keyframes sr-recede { to { opacity: 0; transform: scale(.94); filter: blur(4px); } }
@keyframes sr-iris { from { clip-path: circle(0 at var(--wx, 50%) var(--wy, 0)); } to { clip-path: circle(150% at var(--wx, 50%) var(--wy, 0)); } }

